```python
def count_sum_increases(readings, k):
    if k <= 0 or len(readings) < 2 * k:
        return 0
    s = sum(readings[:k])
    count = 0
    for i in range(k, len(readings) - k + 1):
        s += readings[i] - readings[i - k]
        if s > sum(readings[i - k:i]):
            count += 1
    return count
```

